package pe.clinica.cardenas.financeservice.service;
import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.ParameterizedTypeReference;import org.springframework.http.HttpHeaders;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Service public class EncounterClient {
 private static final Logger log=LoggerFactory.getLogger(EncounterClient.class);private final RestClient client;
 public EncounterClient(@Value("${services.encounters:http://localhost:8092}")String url){client=RestClient.create(url);}
 public void reconcile(Long id,BigDecimal amount,String ref,LocalDateTime paidAt,String auth){if(id==null)throw new IllegalArgumentException("Debe seleccionar un tratamiento pendiente");client.post().uri("/api/encounters/{id}/payments/reconcile",id).header(HttpHeaders.AUTHORIZATION,auth).body(Map.of("amount",amount,"reference",ref==null?"":ref,"paidAt",paidAt==null?LocalDateTime.now():paidAt)).retrieve().toBodilessEntity();}
 public List<Map<String,Object>> treatments(String auth){List<Map<String,Object>> out=client.get().uri("/api/treatments/all").header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(new ParameterizedTypeReference<List<Map<String,Object>>>(){});return out==null?List.of():out;}
 public List<Map<String,Object>> proformas(String auth){List<Map<String,Object>> out=client.get().uri("/api/proformas?financial=false").header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(new ParameterizedTypeReference<List<Map<String,Object>>>(){});return out==null?List.of():out;}
 public Map<String,Object> proformaBase(Long id,String auth){Map<String,Object> out=client.get().uri("/api/proformas/{id}/billing-base",id).header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(new ParameterizedTypeReference<Map<String,Object>>(){});return out==null?Map.of():out;}
 public void linkProformaPayment(Long encounterId,BigDecimal amount,String ref,LocalDateTime paidAt,String auth){if(encounterId==null)return;client.post().uri("/api/encounters/{id}/payments/link",encounterId).header(HttpHeaders.AUTHORIZATION,auth).body(Map.of("amount",amount,"reference",ref==null?"":ref,"paidAt",paidAt==null?LocalDateTime.now():paidAt)).retrieve().toBodilessEntity();}
 public List<Map<String,Object>> paymentContext(Long patientId,String auth){if(patientId==null)return List.of();List<Map<String,Object>> out=client.get().uri("/api/encounters/patients/{patientId}/payment-context",patientId).header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(new ParameterizedTypeReference<List<Map<String,Object>>>(){});return out==null?List.of():out;}
 public List<Map<String,Object>> encounters(String auth){try{List<Map<String,Object>> out=client.get().uri("/api/encounters").header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(new ParameterizedTypeReference<List<Map<String,Object>>>(){});return out==null?List.of():out;}catch(Exception e){log.warn("Historial de atenciones no disponible para clasificación financiera: {}",e.getMessage());return List.of();}}
 public List<Map<String,Object>> pendingTreatments(Long patientId,String auth){if(patientId==null)return List.of();List<Map<String,Object>> out=client.get().uri("/api/encounters/patients/{patientId}/pending-treatments",patientId).header(HttpHeaders.AUTHORIZATION,auth).retrieve().body(new ParameterizedTypeReference<List<Map<String,Object>>>(){});return out==null?List.of():out;}
 public void audit(String entityType,String entityId,String action,Object before,Object after,String reason,String auth){try{Map<String,Object>b=new LinkedHashMap<>();b.put("module","FINANZAS");b.put("entityType",entityType);b.put("entityId",entityId);b.put("action",action);b.put("before",before);b.put("after",after);b.put("reason",reason);client.post().uri("/api/audit/events").header(HttpHeaders.AUTHORIZATION,auth).body(b).retrieve().toBodilessEntity();}catch(Exception e){log.warn("Auditoría financiera no disponible: {}",e.getMessage());}}
}
